def source_sha256(project: Path) -> str:
    digest = hashlib.sha256()
    found = False
    for root_name in ("backend", "domain", "frontend"):
        root = project / root_name
        if not root.exists():
            continue
        for path in sorted(root.rglob("*")):
            if any(part in SKIP_SOURCE_PARTS for part in path.relative_to(project).parts):
                continue
            if path.is_symlink():
                raise GateError(f"project source contains symlink: {path}")
            if not path.is_file():
                continue
            found = True
            relative = path.relative_to(project).as_posix()
            digest.update(relative.encode("utf-8"))
            digest.update(b"\0")
            digest.update(sha256_file(path).encode("ascii"))
            digest.update(b"\n")
    return digest.hexdigest() if found else ""


def nested_sha(document, keys: tuple[str, ...]) -> str:
    if isinstance(document, dict):
        for key, value in document.items():
            if key in keys and isinstance(value, str) and re.fullmatch(r"[0-9a-f]{64}", value):
                return value
            found = nested_sha(value, keys)
            if found:
                return found
    elif isinstance(document, list):
        for value in document:
            found = nested_sha(value, keys)
            if found:
                return found
    return ""


